begin;

set local lock_timeout = '10s';

create temp table phase1c_rb_gate_ok (step text primary key) on commit drop;
create temp table phase1c_rb_gate (
  step text constraint phase1c_rollback_guard_did_not_pass references phase1c_rb_gate_ok deferrable initially deferred
) on commit drop;
insert into phase1c_rb_gate values ('rollback role'), ('rollback preflight'), ('rollback postcondition');

do $role$
begin
  if current_user <> 'postgres' then
    raise exception 'Phase 1C rollback: must run as role postgres (current_user=%, session_user=%); aborting before any change',
      current_user, session_user using errcode = '42501';
  end if;
  insert into pg_temp.phase1c_rb_gate_ok values ('rollback role');
