       set_config('phase1c_rb.approved_by', :'approved_by', true),
       set_config('phase1c_rb.backup_ref', :'backup_ref', true),
       set_config('phase1c_rb.export_sha256', :'export_sha256', true);

create temp table phase1c_rb_before (k text primary key, v text) on commit drop;

-- Digest of a table's rows, used before and after to prove they are unchanged.
create function pg_temp.phase1c_rb_digest(p_table text) returns text language plpgsql as $f$
declare
  v text;
begin
  if p_table = 'public.drivers' then   -- the rollback restores drivers.status only
    select md5(coalesce(string_agg((to_jsonb(d) - 'status')::text, E'\n' order by d.id), '')) into v from public.drivers d;
  else
    execute format('select md5(coalesce(string_agg(to_jsonb(x)::text, E''\n'' order by to_jsonb(x)::text), '''')) from %s x', p_table)
      into v;
  end if;
  return v;
end
$f$;

-- ---------------------------------------------------------------------
-- PREFLIGHT: refuse unless this is the expected database, with Phase 1C
-- applied by the supported procedure and in its reviewed state.
-- ---------------------------------------------------------------------
do $preflight$
declare
  problems text[] := '{}';
  storage_present boolean := to_regclass('storage.objects') is not null;
  want text[];
  v text;
  t text;
begin
  if current_user <> 'postgres' then
    problems := problems || format('must run as role postgres (current_user=%s)', current_user);
  end if;
  if coalesce(current_setting('phase1c_rb.approved_by', true), '') !~ '\S' then
    problems := problems || 'approved_by is empty'::text;
  end if;
  if coalesce(current_setting('phase1c_rb.backup_ref', true), '') !~ '\S' then
    problems := problems || 'backup_ref is empty'::text;
  end if;
  if coalesce(current_setting('phase1c_rb.export_sha256', true), '') !~ '^[0-9a-f]{64}$' then
    problems := problems || 'export_sha256 is not a SHA-256 (the audit export must be made first)'::text;
  end if;
  if to_regclass('public.staff_roles') is null or to_regclass('public.security_audit_log') is null
     or to_regclass('public.kitchens') is null or to_regprocedure('public.containment_violations()') is null then
    problems := problems || 'Phase 1C is not applied here (nothing to roll back)'::text;
  else
    execute $q$select coalesce(string_agg(target_user_id::text, ','), 'none') from public.security_audit_log
                where action = 'staff_role.seed_initial_admin'$q$ into v;
    if v is distinct from current_setting('phase1c_rb.expected_admin', true) then
      problems := problems || format('unexpected database: its initial-admin seed record is %s, expected %s',
                                     v, current_setting('phase1c_rb.expected_admin', true));
    end if;
    execute $q$select string_agg(c.category || ': ' || c.object || ' - ' || c.problem, ' | ')
                 from public.containment_violations() c
                where not (c.category = 'storage' and to_regclass('storage.objects') is null)$q$ into v;
    if v is not null then
      problems := problems || ('Phase 1C is not in its reviewed state (containment_violations): ' || v);
    end if;
  end if;
  if storage_present and not exists (select 1 from pg_policies where schemaname = 'storage'
                                      and policyname in ('staff_admin_select_meal_images', 'staff_admin_insert_meal_images', 'staff_admin_update_meal_images', 'staff_admin_delete_meal_images')) then
    problems := problems || 'storage schema present but the Phase 1C storage migration is not applied'::text;
  end if;
  -- Migration history (supabase db push): the Phase 1C versions are
  -- recorded and are the newest (a later migration may depend on them).
  want := case when storage_present then array['20261016170000', '20261016171000'] else array['20261016170000'] end;
  if to_regclass('supabase_migrations.schema_migrations') is null then
    problems := problems || 'supabase_migrations.schema_migrations missing (Phase 1C not applied with the supported procedure)'::text;
  else
    execute 'select string_agg(x, '','') from unnest($1) x
              where not exists (select 1 from supabase_migrations.schema_migrations m where m.version = x)' into v using want;
    if v is not null then problems := problems || ('migration history lacks ' || v); end if;
    execute $q$select string_agg(version, ',' order by version) from supabase_migrations.schema_migrations
                where version > '20261016171000'$q$ into v;
    if v is not null then problems := problems || ('later migrations are recorded (' || v || '); they must be rolled back first'); end if;
  end if;
  if cardinality(problems) > 0 then
    raise exception 'Phase 1C rollback preflight failed; aborting the rollback transaction (its COMMIT cannot succeed): %',
      array_to_string(problems, ' | ') using errcode = 'P0001';
  end if;
  -- What must be the same afterwards: preserved data, archived row counts.
  foreach t in array array['orders', 'order_items', 'order_status_updates', 'kiosks', 'products', 'stock_movements', 'daily_closings', 'user_profiles', 'meals', 'collaborators', 'collaborator_orders', 'collaborator_payouts', 'collaborator_analytics', 'cash_collections', 'driver_payouts', 'driver_weekly_earnings', 'financial_transactions', 'bank_accounts', 'admins', 'admin_logs', 'platform_settings', 'driver_push_tokens', 'user_push_tokens', 'drivers'] loop
    insert into pg_temp.phase1c_rb_before values ('data public.' || t, pg_temp.phase1c_rb_digest('public.' || t));
  end loop;
  if storage_present then
    insert into pg_temp.phase1c_rb_before values ('data storage.objects', pg_temp.phase1c_rb_digest('storage.objects'));
  end if;
  foreach t in array array['security_audit_log', 'staff_roles', 'kitchens'] loop
    execute format('select count(*)::text from public.%I', t) into v;
    insert into pg_temp.phase1c_rb_before values ('count ' || t, v);
  end loop;
  insert into pg_temp.phase1c_rb_before values ('storage', storage_present::text);
  insert into pg_temp.phase1c_rb_gate_ok values ('rollback preflight');
end
$preflight$;

-- =====================================================================
-- PART 1: storage (20261016171000_phase1c_storage_meal_images). Skipped where no storage schema exists.
-- The meal-images bucket limits are restored EXACTLY to the values the
-- migration recorded in security_audit_log (SQL NULL where the recorded
-- old value is JSON null). No object row is changed.
-- =====================================================================
do $bucket$
declare
  rec jsonb;
begin
  if to_regclass('storage.buckets') is null then
    return;
  end if;
  select l.details into rec
    from public.security_audit_log l
   where l.action = 'storage.bucket.limits_set' and l.details ->> 'bucket' = 'meal-images'
   order by l.id desc limit 1;
  if rec is null then
    raise notice 'no recorded bucket change: meal-images settings left unchanged';
    return;
  end if;
  update storage.buckets
     set file_size_limit = (rec ->> 'old_file_size_limit')::bigint,
         allowed_mime_types = case when jsonb_typeof(rec -> 'old_allowed_mime_types') = 'array'
                                   then array(select jsonb_array_elements_text(rec -> 'old_allowed_mime_types'))
                                   else null end
   where id = 'meal-images';
end
$bucket$;

do $storage_policies$
begin
  if to_regclass('storage.objects') is null then
    return;
  end if;
  drop policy if exists "staff_admin_select_meal_images" on storage."objects";
  drop policy if exists "staff_admin_insert_meal_images" on storage."objects";
  drop policy if exists "staff_admin_update_meal_images" on storage."objects";
  drop policy if exists "staff_admin_delete_meal_images" on storage."objects";
  drop policy if exists "Authenticated users can upload" on storage."objects";
  execute $p$create policy "Authenticated users can upload" on storage."objects" as permissive for insert to public
  with check (((bucket_id = 'meal-images'::text) AND (auth.role() = 'authenticated'::text)))$p$;
  drop policy if exists "Users can update own uploads" on storage."objects";
  execute $p$create policy "Users can update own uploads" on storage."objects" as permissive for update to public
  using (((bucket_id = 'meal-images'::text) AND (auth.uid() = owner)))$p$;
  drop policy if exists "Users can delete own uploads" on storage."objects";
  execute $p$create policy "Users can delete own uploads" on storage."objects" as permissive for delete to public
  using (((bucket_id = 'meal-images'::text) AND (auth.uid() = owner)))$p$;
  drop policy if exists "Public Access" on storage."objects";
  execute $p$create policy "Public Access" on storage."objects" as permissive for select to public
  using ((bucket_id = 'meal-images'::text))$p$;
end
$storage_policies$;

