revoke update (first_name, last_name, phone, current_latitude, current_longitude, last_location_update, updated_at)
  on public.drivers from authenticated;
grant all on public."admin_logs", public."admins", public."bank_accounts", public."cash_collections", public."collaborator_analytics", public."collaborator_orders", public."collaborator_payouts", public."collaborators", public."daily_closings", public."driver_payouts", public."driver_push_tokens", public."driver_weekly_earnings", public."drivers", public."financial_transactions", public."kiosks", public."meals", public."order_items", public."order_status_updates", public."orders", public."platform_settings", public."products", public."stock_movements", public."user_profiles", public."user_push_tokens" to anon, authenticated;

-- 6. Function privileges and configuration as observed.
grant execute on function public.calculate_collaborator_revenue_split() to public, anon, authenticated;
alter function public.calculate_collaborator_revenue_split() reset all;
grant execute on function public.calculate_driver_weekly_earnings() to public, anon, authenticated;
alter function public.calculate_driver_weekly_earnings() reset all;
grant execute on function public.create_order_transaction(text, uuid, jsonb, numeric, text, text) to public, anon, authenticated;
alter function public.create_order_transaction(text, uuid, jsonb, numeric, text, text) reset all;
grant execute on function public.rls_auto_enable() to public, anon, authenticated;
grant execute on function public.update_collaborator_analytics() to public, anon, authenticated;
alter function public.update_collaborator_analytics() reset all;

-- 7. New tables: ARCHIVED (never dropped) into a private schema whose
--    comment records the approval, then the new functions are dropped.
create temp table phase1c_rb_archive (name text) on commit drop;
do $archive$
declare
  arch text := 'phase1c_archive_' || to_char(clock_timestamp() at time zone 'UTC', 'YYYYMMDD"_"HH24MISS');
  t text;
  r record;
begin
  execute format('create schema %I', arch);
  execute format('revoke all on schema %I from public, anon, authenticated, service_role', arch);
  execute format('comment on schema %I is %L', arch,
                 format('Phase 1C rollback archive. Rolled back at %s UTC; approved by %s; backup %s; audit export sha256 %s',
                        to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
                        current_setting('phase1c_rb.approved_by'), current_setting('phase1c_rb.backup_ref'),
                        current_setting('phase1c_rb.export_sha256')));
  foreach t in array array['security_audit_log', 'staff_roles', 'kitchens'] loop
    for r in select tgname from pg_trigger where tgrelid = ('public.' || t)::regclass and not tgisinternal loop
      execute format('drop trigger %I on public.%I', r.tgname, t);
    end loop;
    for r in select policyname from pg_policies where schemaname = 'public' and tablename = t loop
      execute format('drop policy %I on public.%I', r.policyname, t);
    end loop;
    for r in select conname from pg_constraint
              where conrelid = ('public.' || t)::regclass and contype = 'f' and confrelid = 'auth.users'::regclass loop
      execute format('alter table public.%I drop constraint %I', t, r.conname);
    end loop;
    execute format('revoke all on public.%I from public, anon, authenticated, service_role', t);
    execute format('alter table public.%I set schema %I', t, arch);
  end loop;
  execute format('create table %I.drivers_status_reconciliation as select * from pg_temp.phase1c_rb_drivers', arch);
  insert into pg_temp.phase1c_rb_archive values (arch);
  raise notice 'Phase 1C rollback: kitchens, staff_roles and security_audit_log archived in schema %', arch;
  raise notice 'Phase 1C rollback: % normalised driver(s) restored to their legacy status, % left for manual reconciliation (%.drivers_status_reconciliation)',
    (select count(*) from pg_temp.phase1c_rb_drivers where restored), (select count(*) from pg_temp.phase1c_rb_drivers where not restored), arch;
end
$archive$;
drop function public.containment_violations();
drop function public.set_driver_availability(boolean);
drop function public.enforce_driver_availability();
drop function public.assign_staff_role(uuid, text, uuid);
drop function public.revoke_staff_role(uuid, text, uuid);
drop function public.security_audit_log_append_only();
drop function public.staff_roles_require_admin();
drop function public.staff_roles_serialize();
drop function public.staff_roles_driver_offline();
drop function public.staff_roles_no_truncate();
drop function public.has_staff_role(text);

-- 8. Default privileges back to the observed Supabase defaults.
alter default privileges in schema public grant all on tables    to anon, authenticated;
alter default privileges in schema public grant all on sequences to anon, authenticated;
alter default privileges in schema public grant all on functions to anon, authenticated;
alter default privileges grant execute on functions to public;

-- 9. Migration history: the Phase 1C versions are no longer applied.
do $history$
declare
  n int;
  want int := case when (select v from pg_temp.phase1c_rb_before where k = 'storage') = 'true' then 2 else 1 end;
begin
  delete from supabase_migrations.schema_migrations where version in ('20261016170000', '20261016171000');
  get diagnostics n = row_count;
  if n <> want then
    raise exception 'Phase 1C rollback: removed % migration-history rows, expected %', n, want;
  end if;
end
$history$;

-- ---------------------------------------------------------------------
-- POSTCONDITION: the 2026-10-15 policies, archive complete, preserved data
-- unchanged. Otherwise COMMIT cannot succeed.
-- ---------------------------------------------------------------------
do $post$
declare
  problems text[] := '{}';
  arch text := (select name from pg_temp.phase1c_rb_archive);
  r record;
  v text;
begin
  if to_regclass('public.staff_roles') is not null or to_regclass('public.security_audit_log') is not null
     or to_regclass('public.kitchens') is not null then
    problems := problems || 'a Phase 1C table is still in public'::text;
  end if;
  select string_agg(p.oid::regprocedure::text, ', ') into v from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname in ('containment_violations', 'has_staff_role', 'assign_staff_role', 'revoke_staff_role',
                       'set_driver_availability', 'enforce_driver_availability', 'enforce_profile_privilege_guard',
                       'security_audit_log_append_only', 'staff_roles_require_admin', 'staff_roles_serialize',
                       'staff_roles_driver_offline', 'staff_roles_no_truncate');
  if v is not null then problems := problems || ('Phase 1C functions still present: ' || v); end if;
  if md5(coalesce((select string_agg(tablename || '|' || policyname || '|' || cmd || '|' ||
            array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''),
            E'\n' order by tablename collate "C", policyname collate "C")
       from pg_policies where schemaname = 'public'), '')) <> 'd2cb0f4d853918df06ca1d68a52b6096' then
    problems := problems || 'public policies are not exactly the 2026-10-15 evidence'::text;
  end if;
  if (select b.v from pg_temp.phase1c_rb_before b where b.k = 'storage') = 'true'
     and md5(coalesce((select string_agg(tablename || '|' || policyname || '|' || cmd || '|' ||
            array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''),
            E'\n' order by tablename collate "C", policyname collate "C")
       from pg_policies where schemaname = 'storage'), '')) <> '8aa1ab5db6b161453a493c3c5274dd84' then
    problems := problems || 'storage policies are not exactly the 2026-10-15 evidence'::text;
  end if;
  if exists (select 1 from pg_constraint where conrelid = 'public.drivers'::regclass
              and conname = 'drivers_status_availability_check') then
    problems := problems || 'drivers availability constraint still present'::text;
  end if;
  for r in select b.k, b.v as before from pg_temp.phase1c_rb_before b where b.k like 'count %' loop
    execute format('select count(*)::text from %I.%I', arch, substr(r.k, 7)) into v;
    if v is distinct from r.before then
      problems := problems || format('archive %s.%s holds %s rows, expected %s', arch, substr(r.k, 7), v, r.before);
    end if;
  end loop;
  for r in select b.k, b.v as before from pg_temp.phase1c_rb_before b where b.k like 'data %' loop
    if pg_temp.phase1c_rb_digest(substr(r.k, 6)) is distinct from r.before then
      problems := problems || ('preserved data changed: ' || substr(r.k, 6));
    end if;
  end loop;
  if current_user <> 'postgres' then
    problems := problems || format('must run as role postgres (current_user=%s)', current_user);
  end if;
  if cardinality(problems) > 0 then
    raise exception 'Phase 1C rollback postcondition failed; aborting the rollback transaction (its COMMIT cannot succeed): %',
      array_to_string(problems, ' | ') using errcode = 'P0001';
  end if;
  insert into pg_temp.phase1c_rb_gate_ok values ('rollback postcondition');
end
$post$;

commit;
